#!/usr/bin/env python3
import os
import re
import subprocess
import sys

# This script parses Dawn CMakeLists.txt files and creates a .bzl file with the files extracted.
# It uses a structured parser to handle variables and conditional blocks.
#
# Generates file lists dynamically, including querying custom Python generators
# with the --print-cmake-outputs flag to ensure build-time autogenerated files
# are cleanly and automatically tracked without any manual hardcoding.

class CMakeValue:
    """Represents a value bound to a CMake variable along with its scoping conditions."""
    def __init__(self, value, conditions):
        self.value = value
        self.conditions = conditions

class CMakeParser:
    def __init__(self, prefix, rel_path, dawn_root):
        self.prefix = prefix
        self.rel_path = rel_path
        self.dawn_root = dawn_root
        self.variables = {
            "DAWN_INCLUDE_DIR": [CMakeValue("include", [])],
            "DAWN_SRC_DIR": [CMakeValue("src", [])],
        }
        self.generated_hdrs = set()
        # output_vars[prefix_with_conditions][group] = set of files
        self.output_vars = {}
        self.current_conditions = []

    def slugify_condition(self, cond):
        # Remove parentheses and common CMake operators that don't look good in variable names
        cond = cond.replace("(", "").replace(")", "")
        # Remove DAWN_ENABLE_ and DAWN_ as requested
        cond = cond.replace("DAWN_ENABLE_", "").replace("DAWN_", "")
        # Replace non-alphanumeric with _
        cond = re.sub(r'[^a-zA-Z0-9]', '_', cond)
        # Clean up double underscores and remove leading/trailing underscores
        cond = re.sub(r'_+', '_', cond).strip('_')
        return cond.upper()

    def get_prefix_for_conditions(self, conds):
        if not conds:
            return self.prefix
        cond_slug = "_".join(self.slugify_condition(c) for c in conds)
        return f"{self.prefix}_{cond_slug}"

    def get_current_prefix(self):
        return self.get_prefix_for_conditions(self.current_conditions)

    def resolve_var(self, var_name):
        """Resolves a CMake variable, expanding nested variable references.
        
        Returns a list of CMakeValue objects representing all values bound to the variable
        along with the condition lists under which they were defined/appended.
        """
        if var_name not in self.variables:
            return [CMakeValue(f"${{{var_name}}}", [])]
        
        vals = self.variables[var_name]
        resolved = []
        for cv in vals:
            v = cv.value
            conds = cv.conditions
            if isinstance(v, str) and v.startswith("${") and v.endswith("}"):
                inner = v[2:-1]
                if inner != var_name:
                    resolved.extend(self.resolve_var(inner))
                else:
                    resolved.append(cv)
            else:
                resolved.append(cv)
        return resolved

    def expand_string(self, s):
        def repl(match):
            var_name = match.group(1)
            resolved = self.resolve_var(var_name)
            # Use the first resolved value for simplicity in path expansion
            return str(resolved[0].value) if resolved else ""
        
        return re.sub(r'\${([^}]+)}', repl, s)

    def clean_path(self, path):
        path = self.expand_string(path)
        # Handle generator and other paths starting with variables or specific directories
        if path.startswith("${Dawn_SOURCE_DIR}/"):
            path = path[len("${Dawn_SOURCE_DIR}/"):]
        if path.startswith("${CMake_SOURCE_DIR}/"):
            path = path[len("${CMake_SOURCE_DIR}/"):]
            
        if not path.startswith("include/") and not path.startswith("src/") and not path.startswith("generator/"):
            path = os.path.join(self.rel_path, path)
        return os.path.normpath(path)

    def _find_closing_paren(self, content, start_pos):
        """Finds the index of the matching closing parenthesis, handling nested ones."""
        count = 0
        for i in range(start_pos, len(content)):
            if content[i] == '(':
                count += 1
            elif content[i] == ')':
                count -= 1
                if count == 0:
                    return i
        return -1

    def parse(self, content):
        # Remove comments
        content = re.sub(r'#.*', '', content)
        
        pos = 0
        while pos < len(content):
            # Find next command
            match = re.search(r'(\w+)\s*\(', content[pos:])
            if not match:
                break
            
            cmd_name = match.group(1).lower()
            start_paren = pos + match.end() - 1
            
            end_paren = self._find_closing_paren(content, start_paren)
            if end_paren == -1:
                break
            
            args_str = content[start_paren+1:end_paren]
            # Parse arguments, respecting quotes
            args_raw = re.findall(r'"([^"]*)"|([^\s()]+)', args_str)
            args = [a[0] or a[1] for a in args_raw if a[0] or a[1]]
            
            self.handle_command(cmd_name, args)
            pos = end_paren + 1

    def _run_generator(self, script, extra_params):
        """Runs the generator Python script with --print-cmake-outputs to get generated files."""
        # Expand extra params if they have variables
        expanded_params = []
        for p in extra_params:
            expanded = self.expand_string(p)
            if expanded.startswith("${Dawn_SOURCE_DIR}/"):
                expanded = expanded[len("${Dawn_SOURCE_DIR}/"):]
            expanded_params.append(expanded)
            
        temp_gl_file = None
        # Look for gl.xml and replace its argument with a valid path if needed
        for idx, param in enumerate(expanded_params):
            if "gl.xml" in param:
                param_path = os.path.join(self.dawn_root, param) if not os.path.isabs(param) else param
                if not os.path.exists(param_path):
                    # We can search for gl.xml under common Skia / Bazel layout locations:
                    fallbacks = [
                        "../opengl-registry/xml/gl.xml", # relative to dawn_root in Skia checkout
                        "third_party/externals/opengl-registry/xml/gl.xml", # relative to Skia root
                    ]
                    found = False
                    for f in fallbacks:
                        # Let's check relative to dawn_root, or Skia root (which is usually current working directory or grandparent)
                        for base in [self.dawn_root, ".", "..", "../.."]:
                            candidate = os.path.normpath(os.path.join(base, f))
                            if os.path.exists(candidate):
                                expanded_params[idx] = os.path.abspath(candidate)
                                found = True
                                break
                        if found:
                            break
                    
                    if not found:
                        import tempfile
                        # Create a minimal valid XML file so the generator doesn't crash on parsing
                        with tempfile.NamedTemporaryFile(mode="w", suffix=".xml", delete=False) as tf:
                            tf.write("<registry></registry>\n")
                            temp_gl_file = tf.name
                        expanded_params[idx] = temp_gl_file
            
        script_path = os.path.join(self.dawn_root, script)
        cmd = [
            sys.executable,
            os.path.abspath(script_path),
            "--template-dir",
            "generator/templates",
            "--root-dir",
            ".",
            "--output-dir",
            ".",  # Required but doesn't affect print-cmake-outputs
        ] + expanded_params + ["--print-cmake-outputs"]

        try:
            res = subprocess.run(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=True,
                cwd=self.dawn_root
            )
            # Replace whitespace with semicolons, then split on semicolons
            raw_out = res.stdout.strip().replace("\n", ";").replace("\r", ";").replace(" ", ";")
            outputs = raw_out.split(";")
            return [os.path.normpath(o) for o in outputs if o]
        except subprocess.CalledProcessError as e:
            print(f"Warning: Failed to run generator '{script_path}': {e}\nStderr:\n{e.stderr}", file=sys.stderr)
            return []
        except Exception as e:
            print(f"Warning: Failed to run generator '{script_path}': {e}", file=sys.stderr)
            return []
        finally:
            if temp_gl_file and os.path.exists(temp_gl_file):
                try:
                    os.remove(temp_gl_file)
                except Exception:
                    pass

    def handle_command(self, name, args):
        if name == "endif":
            if self.current_conditions:
                self.current_conditions.pop()
            return
        elif name == "else":
            if self.current_conditions:
                last = self.current_conditions.pop()
                self.current_conditions.append(f"NOT_{last}")
            return

        if not args:
            return

        if name == "set":
            var_name = args[0]
            values = args[1:]
            self.variables[var_name] = [CMakeValue(val, list(self.current_conditions)) for val in values]
        elif name == "list":
            if len(args) >= 3 and args[0].upper() == "APPEND":
                var_name = args[1]
                values = args[2:]
                if var_name not in self.variables:
                    self.variables[var_name] = []
                self.variables[var_name].extend([CMakeValue(val, list(self.current_conditions)) for val in values])
        elif name == "if":
            self.current_conditions.append(" ".join(args))
        elif name == "elseif":
            if self.current_conditions:
                self.current_conditions.pop()
            self.current_conditions.append(" ".join(args))
        elif name in ["dawngenerator", "dawnjsongenerator"]:
            # Parse the arguments list
            script = None
            output_headers_var = None
            output_sources_var = None
            extra_params = []
            
            # If it's dawnjsongenerator, we default script to "generator/dawn_json_generator.py"
            if name == "dawnjsongenerator":
                script = "generator/dawn_json_generator.py"
                # Add default dawnjsongenerator extra parameters
                extra_params.extend([
                    "--dawn-json", "src/dawn/dawn.json",
                    "--wire-json", "src/dawn/dawn_wire.json",
                ])
            
            i = 0
            while i < len(args):
                arg_upper = args[i].upper()
                if arg_upper == "SCRIPT":
                    script = args[i+1]
                    i += 2
                elif arg_upper == "OUTPUT_HEADERS":
                    output_headers_var = args[i+1]
                    i += 2
                elif arg_upper == "OUTPUT_SOURCES":
                    output_sources_var = args[i+1]
                    i += 2
                elif arg_upper == "TARGET" and name == "dawnjsongenerator":
                    extra_params.extend(["--targets", args[i+1]])
                    i += 2
                elif arg_upper == "EXTRA_PARAMETERS":
                    # Collect all subsequent arguments until another keyword or end
                    i += 1
                    keywords = {"SCRIPT", "OUTPUT_HEADERS", "OUTPUT_SOURCES", "EXTRA_PARAMETERS", "TARGET", "PRINT_NAME"}
                    while i < len(args) and args[i].upper() not in keywords:
                        extra_params.append(args[i])
                        i += 1
                else:
                    i += 1

            if script:
                cleaned_script = self.clean_path(script)
                outputs = self._run_generator(cleaned_script, extra_params)
                headers = []
                sources = []
                for o in outputs:
                    ext = os.path.splitext(o)[1].lower()
                    if ext in [".h", ".hpp", ".inl", ".inc"]:
                        headers.append(o)
                        self.generated_hdrs.add(self.clean_path(o))
                    else:
                        sources.append(o)
                
                # Register these files in self.variables
                if output_headers_var:
                    self.variables[output_headers_var] = [CMakeValue(h, list(self.current_conditions)) for h in headers]
                if output_sources_var:
                    self.variables[output_sources_var] = [CMakeValue(s, list(self.current_conditions)) for s in sources]
        elif name == "dawn_add_library":
            # Arguments format: dawn_add_library(target_name [keywords and values] ...)
            target_name = args[0]
            if target_name.startswith("dawn_"):
                prefix_name = target_name[5:]
            else:
                prefix_name = target_name
            
            old_prefix = self.prefix
            self.prefix = prefix_name.upper()

            # We iterate through the arguments from index 1 (skipping target_name).
            all_keywords = {
                "FORCE_STATIC", "FORCE_SHARED", "FORCE_OBJECT", "HEADER_ONLY", "ENABLE_EMSCRIPTEN",
                "UTILITY_TARGET", "HEADERS", "PRIVATE_HEADERS", "SOURCES", "DEPENDS", "PRIVATE_DEPENDS"
            }
            current_keyword = None
            for arg in args[1:]:
                arg_upper = arg.upper()
                if arg_upper in all_keywords:
                    current_keyword = arg_upper
                elif current_keyword in ["HEADERS", "PRIVATE_HEADERS", "SOURCES"]:
                    self.add_to_outputs(current_keyword.lower(), [arg])

            self.prefix = old_prefix

    def add_to_outputs(self, var_name, values):
        """Binds extracted files/headers to their respective target prefix.
        
        If a file was defined under conditional blocks, it will be mapped dynamically
        to its target-specific conditional prefix (e.g. DAWN_COMMON_WIN32). This keeps
        conditional files strictly separated from unconditional/base lists.
        """
        var_name_lower = var_name.lower()
        group = None
        
        # Mapping logic:
        # 'headers' (exactly) -> HDRS
        # anything containing 'headers', 'sources', or 'srcs' -> SRCS
        if var_name_lower == "headers":
            group = "HDRS"
        elif "headers" in var_name_lower or "sources" in var_name_lower or "srcs" in var_name_lower:
            group = "SRCS"
        
        if not group:
            return
        
        for val in values:
            # Handle variable expansions within the list
            if val.startswith("${") and val.endswith("}"):
                inner = val[2:-1]
                # If it's a variable we've seen, expand it
                if inner in self.variables:
                    expanded = self.resolve_var(inner)
                    for cv in expanded:
                        cleaned = self.clean_path(cv.value)
                        if "${" not in cleaned:
                            prefix = self.get_prefix_for_conditions(cv.conditions)
                            if prefix not in self.output_vars:
                                self.output_vars[prefix] = {"HDRS": set(), "SRCS": set()}
                            self.output_vars[prefix][group].add(cleaned)
                    continue
            
            cleaned = self.clean_path(val)
            if "${" not in cleaned:
                prefix = self.get_prefix_for_conditions(self.current_conditions)
                if prefix not in self.output_vars:
                    self.output_vars[prefix] = {"HDRS": set(), "SRCS": set()}
                self.output_vars[prefix][group].add(cleaned)

def main():
    if len(sys.argv) < 3:
        print("Usage: generate_dawn_files.py <dawn_root> <output_bzl>")
        sys.exit(1)

    dawn_root = sys.argv[1]
    output_bzl = sys.argv[2]

    # Target directories and their base prefixes
    targets = [
        ("COMMON", "src/dawn/common"),
        ("NATIVE", "src/dawn/native"),
        ("WIRE", "src/dawn/wire"),
        ("PLATFORM", "src/dawn/platform"),
        ("UTILS", "src/dawn/utils"),
        ("PARTITION_ALLOC", "src/dawn/partition_alloc"),
    ]

    all_output_vars = {}

    for prefix, rel_path in targets:
        cmake_path = os.path.join(dawn_root, rel_path, "CMakeLists.txt")
        if not os.path.exists(cmake_path):
            raise FileNotFoundError(f"CMakeLists.txt not found at {cmake_path}")
        
        with open(cmake_path) as f:
            content = f.read()
        
        parser = CMakeParser(prefix, rel_path, dawn_root)
        parser.parse(content)
        
        # Verify that we extracted some files for this target
        has_files = False
        for groups in parser.output_vars.values():
            for files in groups.values():
                if files:
                    has_files = True
                    break
            if has_files:
                break
        
        if not has_files:
            raise ValueError(
                f"No file lists were generated for target '{prefix}' at '{cmake_path}'. "
                f"This indicates a parser failure or unexpected CMake structure."
            )
        
        # Merge parser outputs into global variable map
        for p, groups in parser.output_vars.items():
            for group, files in groups.items():
                if files:
                    var_name = f"{p}_{group}"
                    if var_name not in all_output_vars:
                        all_output_vars[var_name] = set()
                    all_output_vars[var_name].update(files)

    # Work around upstream Dawn CMakeLists.txt missing vulkan/ImmediatesLayoutVk.h.
    # Note: Because all_output_vars stores sets, if Dawn fixes this upstream and the file is parsed
    # naturally, calling .add() is idempotent and will not introduce any duplicates.
    for var in ["NATIVE_VULKAN_SRCS", "NATIVE_OBJECTS_VULKAN_SRCS"]:
        if var in all_output_vars:
            all_output_vars[var].add("src/dawn/native/vulkan/ImmediatesLayoutVk.h")

    with open(output_bzl, "w") as f:
        f.write('"""\nThis file contains the list of files used to build Dawn.\n\nGenerated by generate_dawn_files.py\n"""\n\n')
        for var_name in sorted(all_output_vars.keys()):
            files = sorted(list(all_output_vars[var_name]))
            f.write(f"{var_name} = [\n")
            for file_path in files:
                f.write(f'    "{file_path}",\n')
            f.write("]\n\n")

if __name__ == "__main__":
    main()
